INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'A', '{"klasse":"A"}'::jsonb, NULL, 'Güteklasse A', 0, '{"rank":1,"methode":"Alle Bewässerungsmethoden","anwendungsbereich_eu":"Alle roh verzehrten Nahrungsmittelpflanzen, deren essbarer Teil unmittelbar mit dem aufbereiteten Wasser in Kontakt kommt und Kulturen, deren unterirdisch im Boden wachsender Wurzelanteil roh verzehrt wird (z. B. Karotten, Zwiebeln, Rote Beete)","karenzzeit_text":"(Bewässerung ohne Einschränkungen und ohne Karenzzeit vor der Ernte)","emitter_tropf_cm":null,"emitter_mikro_cm":null,"laktierend_ausgeschlossen":null,"laktierend_abtrocknung":null,"vorsorge_text":null}'::jsonb, '\hline A & \begin{tabular}{l}
Anwendungsbereich nach EU-WasserWVVO \\
Alle roh verzehrten Nahrungsmittelpflanzen, deren essbarer Teil unmittelbar mit dem aufbereiteten Wasser in Kontakt kommt und Kulturen, deren unterirdisch im Boden wachsender Wurzelanteil roh verzehrt wird (z. B. Karotten, Zwiebeln, Rote Beete) \\
Weitere Spezifikation \\
Landwirtschaft und Gartenbau: \\
- Bewässerung aller Freiland- und Gewächshauskulturen mit allen Bewässerungsmethoden (Bewässerung ohne Einschränkungen und ohne Karenzzeit vor der Ernte) ${ }^{\text {al,b,c,d,d) }}$ \\
- Beregnung zur Bestandskühlung (z. B. im Obst-, Hopfen- und Weinanbau) ${ }^{\text {(c)d,d) }}$ \\
Landschaftsbau und Freiflächenpflege: \\
- Uneingeschränkte Bewässerung aller Freilandflächen inkl. Parks, Sportflächen und privaten Gärten ${ }^{\text {cl,e }}$ \\
Besondere Vorsorgemaßnahmen: \\
- Beherrschbares Risiko bei Schweinefutter ${ }^{(*)}$
\end{tabular} & Alle Bewässerungsmethoden \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-1' AND edition = '2025-07' AND table_code = 'TAB7_CLASS'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'B-1', '{"klasse":"B-1"}'::jsonb, NULL, 'Güteklasse B-1', 1, '{"rank":2,"methode":"Alle Bewässerungsmethoden","anwendungsbereich_eu":"Roh verzehrte Nahrungsmittelpflanzen, deren essbarer Teil über dem Boden erzeugt wird und nicht unmittelbar mit dem aufbereiteten Wasser in Kontakt kommt, verarbeitete Nahrungsmittelpflanzen und Non-Food-Kulturen, einschließlich Futterkulturen für milch- und fleischerzeugende Tiere","karenzzeit_text":"Bei einer Beweidung durch laktierendes Milchvieh muss eine vollständige Abtrocknung des Bestands vor dem Weidegang erfolgt sein ${ }^{\\text {al }}$. Empfohlen wird ein Bewässerungsstopp mit aufbereitetem Wasser von 2 Wochen ${ }^{\\text {b) }}$ vor dem Weidegang durch laktierendes Vieh","emitter_tropf_cm":null,"emitter_mikro_cm":null,"laktierend_ausgeschlossen":false,"laktierend_abtrocknung":true,"vorsorge_text":"Bei einer Beweidung durch laktierendes Milchvieh muss eine vollständige Abtrocknung des Bestands vor dem Weidegang erfolgt sein ${ }^{\\text {al }}$. Empfohlen wird ein Bewässerungsstopp mit aufbereitetem Wasser von 2 Wochen ${ }^{\\text {b) }}$ vor dem Weidegang durch laktierendes Vieh"}'::jsonb, '\hline B-1 & \begin{tabular}{l}
Anwendungsbereich nach EU-WasserWVVO \\
Roh verzehrte Nahrungsmittelpflanzen, deren essbarer Teil über dem Boden erzeugt wird und nicht unmittelbar mit dem aufbereiteten Wasser in Kontakt kommt, verarbeitete Nahrungsmittelpflanzen und Non-Food-Kulturen, einschließlich Futterkulturen für milch- und fleischerzeugende Tiere \\
Weitere Spezifikation \\
Landwirtschaft und Gartenbau: \\
- Tropfbewässerung von roh verzehrtem Gemüse ohne Kontakt der essbaren Teile mit dem Bewässerungswasser ${ }^{\text {a) }}$, Folienabdeckung des bewässerten Bodens wird empfohlen ${ }^{\text {d,el }}$ \\
- Bewässerung von Pflanzen, deren Ernteorgane nicht roh verzehrt werden (z. B. Getreide, Hackfrüchte, Körnermais, Körnerleguminosen) ${ }^{\text {ad,c,d) }}$ \\
- Bewässerung von Weiden, Grünland oder frisch verfüttertem Feldfutter (z. B. Kleegras) ohne Einschränkung ${ }^{\text {al,c,d) }}$ \\
Besondere Vorsorgemaßnahmen: \\
- Beherrschbares Risiko bei Schweinefutter ${ }^{(*)}$ \\
- Bei einer Beweidung durch laktierendes Milchvieh muss eine vollständige Abtrocknung des Bestands vor dem Weidegang erfolgt sein ${ }^{\text {al }}$. Empfohlen wird ein Bewässerungsstopp mit aufbereitetem Wasser von 2 Wochen ${ }^{\text {b) }}$ vor dem Weidegang durch laktierendes Vieh \\
- Keine Ernte von (durch Bewässerungswasser) feuchten oder herabgefallenen Erzeugnissen ${ }^{\text {al }}$
\end{tabular} & Alle Bewässerungsmethoden \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-1' AND edition = '2025-07' AND table_code = 'TAB7_CLASS'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'B-2', '{"klasse":"B-2"}'::jsonb, NULL, 'Güteklasse B-2', 2, '{"rank":3,"methode":"Alle Bewässerungsmethoden","anwendungsbereich_eu":null,"karenzzeit_text":null,"emitter_tropf_cm":null,"emitter_mikro_cm":null,"laktierend_ausgeschlossen":null,"laktierend_abtrocknung":null,"vorsorge_text":null}'::jsonb, '\hline B-2 & \begin{tabular}{l}
Landwirtschaft und Gartenbau: \\
- Einer Pasteurisierung entsprechend verarbeitete (erhitzte) Nahrungsmittel und Non-Food-Kulturen \\
Landschaftsbau und Freiflächenpflege: \\
- Bewässerung von regulär bespielten Rasenflächen auf Sportplätzen inkl. Golf- und Reitplätzen (Voraussetzung: Bewässerung findet nicht während der unmittelbaren Nutzung statt) (alle Bewässerungsmethoden) ${ }^{\text {cl,el }}$ \\
- Bewässerung von Liegewiesen in öffentlichen Parkanlagen außerhalb regulärer Nutzungszeiten sowie mit steuerbarem Zugang (alle Bewässerungsmethoden) ${ }^{\text {el }}$ \\
- Bewässerung von Straßenbegleitgrün (Sträucher, Hecken, Wiesen, Gleisbettbegrünungen etc.) (alle Bewässerungsmethoden) ${ }^{\text {el }}$ \\
- Bewässerung von sonstigen Wiesen- und Rasenflächen in öffentlichen Parkanlagen, Landschaftsgärten und Landschaftsparks sowie sonstiger Frei- und Grünflächen im urbanen Bereich außerhalb von Parkanlagen (außerhalb regulärer Nutzungszeiten) (alle Bewässerungsmethoden) ${ }^{\text {el }}$
\end{tabular} & Alle Bewässerungsmethoden \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-1' AND edition = '2025-07' AND table_code = 'TAB7_CLASS'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'C-1', '{"klasse":"C-1"}'::jsonb, NULL, 'Güteklasse C-1', 3, '{"rank":4,"methode":"Tropfbewässerung oder eine andere Bewäs-serungsmethode, bei der ein unmittelbarer Kontakt mit dem essbaren Teil der Pflanze vermieden wird","anwendungsbereich_eu":"Roh verzehrte Nahrungsmittelpflanzen, deren essbarer Teil über dem Boden erzeugt wird und nicht unmittelbar mit dem aufbereiteten Wasser in Kontakt kommt, verarbeitete Nahrungsmittelpflanzen und Non-FoodKulturen, einschließlich Futterkulturen für milch- und fleischerzeugende Tiere","karenzzeit_text":"Bewässerung von Weiden, Grünland oder anderen frischen Feldfutterpflanzen (z. B. Kleegras) mit aufbereitetem Wasser bis maximal 5 Tage vor dem Schnitt oder Weidegang durch nicht laktierendes Vieh ${ }^{\\text {al, cl, d) }}$, besser maximal 2 Wochen ${ }^{\\text {b) }}$","emitter_tropf_cm":25,"emitter_mikro_cm":50,"laktierend_ausgeschlossen":true,"laktierend_abtrocknung":null,"vorsorge_text":"Eine Beweidung durch laktierendes Vieh bei der Verwendung der Güteklasse C wird grundsätzlich ausgeschlossen."}'::jsonb, '\hline C-1 & \begin{tabular}{l}
Anwendungsbereich nach EU-WasserWVVO \\
Roh verzehrte Nahrungsmittelpflanzen, deren essbarer Teil über dem Boden erzeugt wird und nicht unmittelbar mit dem aufbereiteten Wasser in Kontakt kommt, verarbeitete Nahrungsmittelpflanzen und Non-FoodKulturen, einschließlich Futterkulturen für milch- und fleischerzeugende Tiere \\
Weitere Spezifikation \\
Landwirtschaft und Gartenbau: \\
- Unterflurbewässerung von roh verzehrtem Gemüse, dessen essbarer Teil über dem Boden erzeugt wird (kein Kontakt der essbaren Teile mit dem Bewässerungswasser durch Folienabdeckung des bewässerten Bodens vorausgesetztt ${ }^{\text {a,c,d,d) }}$ \\
- Bewässerung von Obst und Gemüse zur Konservierung inkl. Obst und Gemüse zur Saftherstellung (alle Bewässerungsarten) ${ }^{\text {b,cl,d) }}$ \\
- Tropf- oder Unterflurbewässerung von verarbeiteten Nahrungsmittelpflanzen (z. B. Getreide, Körnermais, Körnerleguminosen) ${ }^{\text {al, cl,d) }}$ \\
- Tropfbewässerung von Dauerkulturen (Hopfen, Obst und Wein), wenn Ernteprodukte mindestens 25 cm Abstand zum Emitter aufweisen ${ }^{\text {cl,d) }}$ \\
- Mikrosprühbewässerung von Dauerkulturen (Hopfen, Obst und Wein), wenn Ernteprodukte mindestens 50 cm Abstand zum Emitter aufweisen ${ }^{\text {cl,d) }}$ \\
- Bewässerung von nicht verzehrbaren Kulturen im Gewächshaus oder unter Folie ${ }^{\text {b) }}$ \\
- Bewässerung von Weiden, Grünland oder anderen frischen Feldfutterpflanzen (z. B. Kleegras) mit aufbereitetem Wasser bis maximal 5 Tage vor dem Schnitt oder Weidegang durch nicht laktierendes Vieh ${ }^{\text {al, cl, d) }}$, besser maximal 2 Wochen ${ }^{\text {b) }}$ \\
- Bewässerung von Pflanzen zur Heu- oder Futtersilageproduktion mit aufbereitetem Wasser bis maximal 5 Tage vor der Ernte ${ }^{\text {cl,d) }}$, besser maximal 2 Wochen ${ }^{\text {b) }}$
\end{tabular} & Tropfbewässerung oder eine andere Bewäs-serungsmethode, bei der ein unmittelbarer Kontakt mit dem essbaren Teil der Pflanze vermieden wird \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-1' AND edition = '2025-07' AND table_code = 'TAB7_CLASS'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'C-2', '{"klasse":"C-2"}'::jsonb, NULL, 'Güteklasse C-2', 4, '{"rank":5,"methode":"Alle Bewässerungsmethoden","anwendungsbereich_eu":null,"karenzzeit_text":null,"emitter_tropf_cm":null,"emitter_mikro_cm":null,"laktierend_ausgeschlossen":true,"laktierend_abtrocknung":null,"vorsorge_text":"Eine Beweidung durch laktierendes Vieh bei der Verwendung der Güteklasse C wird grundsätzlich ausgeschlossen."}'::jsonb, '\hline C-2 & \begin{tabular}{l}
Landwirtschaft und Gartenbau: \\
- Einer Pasteurisierung entsprechend verarbeitete (erhitzte) Nahrungsmittel und Non-Food-Kulturen \\
Landschaftsbau und Freiflächenpflege: \\
- Bewässerung von regulär bespielten Rasenflächen auf Sportplätzen inkl. Golf- und Reitplätzen außerhalb regulärer Nutzungszeiten sowie mit steuerbarem Zugang und Abtrocknung vor der anschließenden Nutzung ${ }^{\text {bl,d,el }}$ \\
- Bewässerung von Hecken, Sträuchern und sonstigen nicht bespielten Bereichen auf Sportflächen und Sportanlagen inkl. Golf- und Reitplätzen außerhalb der regulären Nutzungszeiten ${ }^{\text {b)d,d,el }}$ \\
- Tropfbewässerung oder bodennahe Bewässerung von Hecken, Sträuchern, Rabatten und Gebüschen im urbanen Bereich sowie in öffentlichen Parkanlagen ${ }^{\text {el }}$ \\
- Tropfbewässerung oder bodennahe Bewässerung bodengebundener oder bodenferner Hauswandbegrünungen ${ }^{\text {el }}$ \\
- Bewässerung von sonstigen Wiesen- und Rasenflächen in öffentlichen Parkanlagen, Landschaftsgärten und Landschaftsparks laußerhalb regulärer Nutzungszeiten) mit steuerbarer Zugangskontrolle ${ }^{\text {bl,d,e) }}$
\end{tabular} & Alle Bewässerungsmethoden \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-1' AND edition = '2025-07' AND table_code = 'TAB7_CLASS'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'D', '{"klasse":"D"}'::jsonb, NULL, 'Güteklasse D', 5, '{"rank":6,"methode":"Alle Bewässerungsmethoden","anwendungsbereich_eu":"Industrie- und Energiepflanzen sowie Pflanzen zur Saatgutgewinnung","karenzzeit_text":"Bewässerung von Weiden, Grünland oder anderen frischen Feldfutterpflanzen (z. B. Kleegras) mit aufbereitetem Wasser bis 4 Wochen vor dem Schnitt oder Weidegang durch nicht laktierendes Vieh ${ }^{\\text {cl, }, \\text { d,e) }}$ · Bewässerung von Grünland oder von anderen Pflanzen zur Heu- oder Silageproduktion mit aufbereitetem Wasser bis 2 Wochen vor der Ernte ${ }^{\\text {bj,cl,d) }}$ · Bewässerung von Pflanzen zur Produktion von Vermehrungssaatgut mit aufbereitetem Wasser bis 30 Tage vor der Ernte ${ }^{\\text {cl,d) }}$","emitter_tropf_cm":null,"emitter_mikro_cm":null,"laktierend_ausgeschlossen":null,"laktierend_abtrocknung":null,"vorsorge_text":null}'::jsonb, '\hline D & \begin{tabular}{l}
Anwendungsbereich nach EU-WasserWVVO \\
Industrie- und Energiepflanzen sowie Pflanzen zur Saatgutgewinnung \\
Weitere Spezifikation \\
Landwirtschaft und Gartenbau: \\
- Frostschutzberegnung bis Fruchtansatz ${ }^{\text {al,el }}$ \\
- Bewässerung von allen Pflanzen zur ausschließlichen Energie- oder Faserproduktion ${ }^{\text {al,b,cl }}$ \\
- Unterflurbewässerung von Hopfen sowie Obst- und Weinbaukulturen ${ }^{\text {cl,d,e) }}$ \\
- Bewässerung von Weiden, Grünland oder anderen frischen Feldfutterpflanzen (z. B. Kleegras) mit aufbereitetem Wasser bis 4 Wochen vor dem Schnitt oder Weidegang durch nicht laktierendes Vieh ${ }^{\text {cl, }, \text { d,e) }}$ \\
- Bewässerung von Grünland oder von anderen Pflanzen zur Heu- oder Silageproduktion mit aufbereitetem Wasser bis 2 Wochen vor der Ernte ${ }^{\text {bj,cl,d) }}$ \\
- Bewässerung von Arzneipflanzen zur industriellen Gewinnung der Arzneistoffe mit aufbereitetem Wasser bis 2 Wochen vor der Ernte ${ }^{\text {a,c,d,d,e) }}$
\end{tabular} & Alle Bewässerungsmethoden \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-1' AND edition = '2025-07' AND table_code = 'TAB7_CLASS'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
